&reftitle.description;
protected stringboolnullYaf_Controller_Abstract::render stringtpl arraynullparameters
Renderiza el script de vista tpl y devuelve la salida, a diferencia de Yaf_Controller_Abstract::display.

&reftitle.returnvalues;

 La salida renderizada como &string; en caso de éxito, o &false; en caso de
 error.

  &reftitle.examples;

   Ejemplo de Yaf_Controller_Abstract::render


<?php
class ProductController extends Yaf_Controller_Abstract
{
    public function indexAction() {
        // no se auto-renderiza la plantilla por omisión
        Yaf_Dispatcher::getInstance()->disableView();

        // renderiza product/index.phtml y devuelve la salida
        // en lugar de enviarla directamente (como haría display())
        $html = $this->render("product/index.phtml", array(
            "products" => array("yaf", "php"),
        ));

        // se post-procesa y se establece como cuerpo de la respuesta
        $this->getResponse()->setBody($html);
    }
}
?>
